css:
.m-2 {
  margin: 0.5rem
}

.ml-10 {
  margin-left: 2.5rem
}

.mr-2 {
  margin-right: 0.5rem
}

.mt-2 {
  margin-top: 0.5rem
}

.mt-4 {
  margin-top: 1rem
}

.flex {
  display: flex
}

.h-12 {
  height: 3rem
}

.h-6 {
  height: 1.5rem
}

.w-12 {
  width: 3rem
}

.w-6 {
  width: 1.5rem
}

.flex-col {
  flex-direction: column
}

.items-start {
  align-items: flex-start
}

.items-end {
  align-items: flex-end
}

.items-center {
  align-items: center
}

.justify-center {
  justify-content: center
}

.rounded-md {
  border-radius: 0.375rem
}

.border {
  border-width: 1px
}

.border-orange-400 {
  --tw-border-opacity: 1;
  border-color: rgb(251 146 60 / var(--tw-border-opacity))
}

.bg-orange-200 {
  --tw-bg-opacity: 1;
  background-color: rgb(254 215 170 / var(--tw-bg-opacity))
}

.bg-orange-700 {
  --tw-bg-opacity: 1;
  background-color: rgb(194 65 12 / var(--tw-bg-opacity))
}

.p-6 {
  padding: 1.5rem
}

.pb-1 {
  padding-bottom: 0.25rem
}

.pb-1\.5 {
  padding-bottom: 0.375rem
}

.pl-4 {
  padding-left: 1rem
}

.pr-4 {
  padding-right: 1rem
}

.pt-1 {
  padding-top: 0.25rem
}

.pt-1\.5 {
  padding-top: 0.375rem
}

.text-base {
  font-size: 1rem;
  line-height: 1.5rem
}

.text-lg {
  font-size: 1.125rem;
  line-height: 1.75rem
}

.font-medium {
  font-weight: 500
}

.text-orange-900 {
  --tw-text-opacity: 1;
  color: rgb(124 45 18 / var(--tw-text-opacity))
}

.text-white {
  --tw-text-opacity: 1;
  color: rgb(255 255 255 / var(--tw-text-opacity))
}

.hover\:bg-orange-800:hover {
  --tw-bg-opacity: 1;
  background-color: rgb(154 52 18 / var(--tw-bg-opacity))
}
